using Aspire.Hosting.Testing;

namespace MyApp.Evaluation;

public class AppHostFixture : IAsyncLifetime
{
    public DistributedApplication App { get; private set; } = default!;

    public async ValueTask InitializeAsync()
    {
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        App = await builder.BuildAsync();
        var cts = new CancellationTokenSource(TimeSpan.FromSeconds(60));
        await App.StartAsync(cts.Token);
    }

    public async ValueTask DisposeAsync()
    {
        await App.StopAsync();
        await App.DisposeAsync();
    }
}

using Aspire.Hosting.Testing;

namespace MyApp.Evaluation;

public class EvaluationTests : IClassFixture<AppHostFixture>
{
    private readonly AppHostFixture _fixture;

    public EvaluationTests(AppHostFixture fixture)
    {
        _fixture = fixture;
    }

    [Fact]
    public void AppStartsSuccessfully()
    {
        Assert.NotNull(_fixture.App);
    }

    [Fact]
    public async Task AllResourcesStarted()
    {
        var cts = new CancellationTokenSource(TimeSpan.FromSeconds(30));
        await _fixture.App.WaitForResources(cts.Token);
    }
}

